(function(){
  if (document.querySelector(".mbsov-mark")) return;
  var header = document.querySelector(".site-header .wrap") || document.querySelector("header");
  if (!header) return;
  var a = document.createElement("a");
  a.className = "mbsov-mark";
  a.href = "https://mbsov.nl/";
  a.title = "MBSOV";
  a.target = "_blank";
  a.rel = "noopener";
  a.innerHTML = '<img src="data:image/png;base64," alt="MBSOV">';
  header.insertBefore(a, header.firstChild);
})();
